        "sabre/dav": "^4.7",
        "smalot/pdfparser": "^2.11",
        "symfony/console": "^7.4",
        "symfony/yaml": "^7.4"
    },
    "require-dev": {
        "barryvdh/laravel-ide-helper": "^3.7",
        "fakerphp/faker": "^1.24",
        "hhxsv5/laravel-s": "~3.8.0",
        "kitloong/laravel-migrations-generator": "^7.4",
